import{_ as e,c as r,o as t,ag as s}from"./chunks/framework.Cycwnjj0.js";const i="/assets/overview-page-of-rports-from-azonpress.DxLdEOlv.webp",v=JSON.parse('{"title":"Reports Overview with AzonPress","description":"","frontmatter":{},"headers":[],"relativePath":"guide/reports/reports-overview.md","filePath":"guide/reports/reports-overview.md"}'),n={name:"guide/reports/reports-overview.md"};function a(l,o,p,g,c,h){return t(),r("div",null,[...o[0]||(o[0]=[s('<h1 id="reports-overview-with-azonpress" tabindex="-1">Reports Overview with AzonPress <a class="header-anchor" href="#reports-overview-with-azonpress" aria-label="Permalink to &quot;Reports Overview with AzonPress&quot;">​</a></h1><p>In AzonPress, the &quot;<strong>Overview</strong>&quot; feature of the <strong>Reports</strong> section displays overall click reports for all your affiliate products with filtering options. This article will guide you through the explanation of the <strong>Overview</strong> of <strong>Reports</strong>.</p><h2 id="overview-of-reports" tabindex="-1">Overview of Reports <a class="header-anchor" href="#overview-of-reports" aria-label="Permalink to &quot;Overview of Reports&quot;">​</a></h2><p>To learn about all the available options under the dashboard overview of Reports, follow the steps with a screenshot below –</p><p>First, go to <strong>Reports</strong> from the <strong>AzonPress Navbar</strong> and the <strong>Overview</strong> page will open automatically. Then, you will get all the options of <strong>Reports Overview</strong> for all your Products.</p><p><strong>All the options for reports overview are briefly explained below:</strong></p><ol><li>Here, you can Filter click reports based on timeframes like <strong>Year</strong> (ongoing year), <strong>Last Month</strong>, <strong>This Month</strong> (ongoing month), <strong>Last Week</strong>, <strong>Today</strong> (ongoing day), and selecting <strong>All</strong> shows the overall report for the entire time range.</li><li>In this option, you can use the <strong>Date Filter</strong> to view reports from a specific timeline.</li><li><strong>Click Tracking Overview</strong>: With this option, you will get an overview of the clicks you receive from your affiliate products. Such as – <ul><li><strong>Total clicks</strong>: All the clicks received from all your products on your site.</li><li><strong>Unique clicks</strong>: All the unique clicks you received from all your products.</li><li><strong>Total Views</strong>: All the views you got from all your products on your site.</li><li><strong>Total countries</strong>: All the number of countries from where you got the clicks.</li></ul></li><li><strong>Click Tracking Report</strong>: Here, you can see your graph of total click reports for the recent days in a line chart.</li></ol><p><img src="'+i+'" alt="Overview Page of Reports From AzonPress"></p><p>If you have any further questions, concerns, or suggestions, please do not hesitate to contact our support team. Thank you.</p><hr>',10)])])}const f=e(n,[["render",a]]);export{v as __pageData,f as default};
